css:
:where(.wtyg-map-site_eyes_network) 0,:where(.wtyg-map-site_eyes_network) 500;0,:where(.wtyg-map-site_eyes_network) 600;1,:where(.wtyg-map-site_eyes_network) 400;1,:where(.wtyg-map-site_eyes_network) 500&family=Spectral:ital,:where(.wtyg-map-site_eyes_network) wght@0,:where(.wtyg-map-site_eyes_network) 300;0,:where(.wtyg-map-site_eyes_network) 400;0,:where(.wtyg-map-site_eyes_network) 600;1,:where(.wtyg-map-site_eyes_network) 300;1,:where(.wtyg-map-site_eyes_network) 400&family=JetBrains+Mono:wght@300;400&display=swap');

:root{--bg:       #111520;
  --paper:    #e8e0d0;
  --muted:    #8a7f6e;
  --accent:   #c8a84b;
  --border:   rgba(200,168,75,0.18);
  --panel-bg: rgba(10,12,18,0.98);
  --c-thinker:     #d4896a;
  --c-counter:     #4a8a6a;
  --c-institution: #6a9fd4;
  --c-government:  #c46a6a;
  --c-media:       #c4aa6a;
  --c-controller:  #c8a84b;}
:where(.wtyg-map-site_eyes_network) *{margin:0; padding:0; box-sizing:border-box;}
:where(.wtyg-map-site_eyes_network){background:var(--bg); color:var(--paper); font-family:'Spectral',serif; overflow:hidden; height:100vh; display:flex; flex-direction:column;}
:where(.wtyg-map-site_eyes_network) header{position:relative; z-index:20; padding:9px 20px;
  background:rgba(8,9,16,0.98); border-bottom:1px solid var(--border);
  display:flex; align-items:stretch; gap:0; flex-shrink:0; min-height:54px;}
:where(.wtyg-map-site_eyes_network) .hd-left{flex:1 1 0; display:flex; align-items:center;
  padding:0 20px 0 0; border-right:1px solid var(--border);}
:where(.wtyg-map-site_eyes_network) .sub{font-size:0.63rem; color:var(--paper); font-style:italic;
  line-height:1.52; font-family:'Spectral',serif;}
:where(.wtyg-map-site_eyes_network) .hd-note{flex:1 1 0; padding:0 18px; display:flex; align-items:center;
  border-right:1px solid var(--border);}
:where(.wtyg-map-site_eyes_network) .hd-note p{font-size:0.62rem; line-height:1.58; color:var(--paper);
  font-style:italic; font-family:'Spectral',serif; margin:0;}
:where(.wtyg-map-site_eyes_network) .hd-note p em{color:#7a8898; font-style:normal; font-weight:500;}
:where(.wtyg-map-site_eyes_network) .legend{flex:1 1 0; padding-left:20px; display:flex; flex-direction:column; justify-content:center; gap:0; overflow:hidden;}
:where(.wtyg-map-site_eyes_network) .li{display:flex; align-items:center; gap:5px; font-size:0.62rem; font-family:'JetBrains Mono',monospace; color:var(--muted); letter-spacing:0.03em; white-space:nowrap;}
:where(.wtyg-map-site_eyes_network) .ld{width:8px; height:8px; border-radius:50%; flex-shrink:0;}
:where(.wtyg-map-site_eyes_network) .lsq{width:12px; height:7px; border-radius:1px; flex-shrink:0;}
:where(.wtyg-map-site_eyes_network) .hint{font-style:italic; font-family:'Spectral',serif; font-size:0.65rem; color:#303848;}
:where(.wtyg-map-site_eyes_network) .leg-group{display:flex; flex-direction:column; gap:2px;}
:where(.wtyg-map-site_eyes_network) .leg-lbl{font-family:'JetBrains Mono',monospace; font-size:0.5rem; letter-spacing:0.1em; text-transform:uppercase; color:#303848; margin-bottom:2px;}
:where(.wtyg-map-site_eyes_network) .hd-quote-note{margin-top:8px; font-size:0.57rem; line-height:1.55;
  color:rgba(220,210,195,0.82); font-style:italic; font-family:'Spectral',serif;}
:where(.wtyg-map-site_eyes_network) .hd-caveat{flex:0 0 auto; max-width:230px; padding:0 16px;
  display:flex; align-items:center;
  border-right:1px solid var(--border);}
:where(.wtyg-map-site_eyes_network) .hd-caveat p{font-size:0.58rem; line-height:1.55; color:#3a4050;
  font-style:italic; font-family:'Spectral',serif; margin:0;}
:where(.wtyg-map-site_eyes_network) .hd-caveat p strong{color:#4a5060; font-style:normal; font-weight:500;}
:where(.wtyg-map-site_eyes_network) .hd-quote{flex:1 1 0; padding:0 20px;
  display:flex; flex-direction:column; justify-content:center;
  border-right:1px solid var(--border);}
:where(.wtyg-map-site_eyes_network) .hd-quote blockquote{margin:0; padding:0;
  font-family:'EB Garamond',serif; font-style:italic;
  font-size:0.64rem; line-height:1.6; color:rgba(220,210,195,0.88);
  border-left:2px solid rgba(200,168,75,0.3); padding-left:8px;}
:where(.wtyg-map-site_eyes_network) .hd-quote cite{display:block; margin-top:4px;
  font-family:'JetBrains Mono',monospace; font-style:normal;
  font-size:0.52rem; letter-spacing:0.06em; color:#3a3020;}
:where(.wtyg-map-site_eyes_network) .wrap{display:flex; width:100vw; flex:1 1 0; min-height:0; overflow:hidden;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="cvs"],#wtyg-noid-cvs){flex:0 0 50%; height:100%; overflow:auto; border-right:1px solid var(--border); position:relative;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="cvs"],#wtyg-noid-cvs) svg{display:block;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="right-pane"],#wtyg-noid-right-pane){flex:0 0 50%; height:100%; display:flex; flex-direction:column; overflow:hidden; min-height:0;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="panel"],#wtyg-noid-panel){flex:0 0 62%; overflow-y:auto; padding:18px 22px 16px;
  background:var(--panel-bg); border-bottom:1px solid var(--border);}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="panel"],#wtyg-noid-panel)::-webkit-scrollbar{width:3px;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="panel"],#wtyg-noid-panel)::-webkit-scrollbar-thumb{background:var(--border); border-radius:2px;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="map-pane"],#wtyg-noid-map-pane){flex:1 1 0; min-height:0; position:relative; background:#0c1018;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="em"],#wtyg-noid-em){position:absolute; bottom:14px; left:14px; width:200px; background:rgba(8,10,18,0.97); border:1px solid var(--border); border-radius:3px; z-index:20;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="em"],#wtyg-noid-em) .em-hd{background:rgba(200,168,75,0.08); border-bottom:1px solid var(--border); padding:5px 9px; font-family:'JetBrains Mono',monospace; font-size:0.55rem; letter-spacing:0.1em; text-transform:uppercase; color:var(--accent); display:flex; justify-content:space-between; cursor:pointer;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="em-body"],#wtyg-noid-em-body){max-height:190px; overflow-y:auto; padding:3px 0;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="em-body"],#wtyg-noid-em-body)::-webkit-scrollbar{width:2px;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="em-body"],#wtyg-noid-em-body)::-webkit-scrollbar-thumb{background:var(--border);}
:where(.wtyg-map-site_eyes_network) .em-gl{font-family:'JetBrains Mono',monospace; font-size:0.49rem; letter-spacing:0.1em; text-transform:uppercase; color:#303848; padding:5px 10px 2px;}
:where(.wtyg-map-site_eyes_network) .em-it{padding:3px 9px; font-size:0.67rem; color:#505868; cursor:pointer; transition:all 0.12s; display:flex; align-items:center; gap:6px; line-height:1.3;}
:where(.wtyg-map-site_eyes_network) .em-it:hover,:where(.wtyg-map-site_eyes_network) .em-it.act{color:var(--paper); background:rgba(200,168,75,0.07);}
:where(.wtyg-map-site_eyes_network) .em-d{width:6px; height:6px; border-radius:50%; flex-shrink:0;}
:where(.wtyg-map-site_eyes_network) .p-ph{text-align:center; padding:20px 10px; color:#2a3040; font-style:italic; font-size:0.82rem; line-height:1.8;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="pc"],#wtyg-noid-pc){display:block;}
:where(.wtyg-map-site_eyes_network) .p-era{font-family:'JetBrains Mono',monospace; font-size:0.59rem; letter-spacing:0.12em; text-transform:uppercase; color:var(--accent); margin-bottom:3px;}
:where(.wtyg-map-site_eyes_network) .p-title{font-family:'EB Garamond',serif; font-size:1.18rem; font-weight:600; color:var(--paper); margin-bottom:3px; line-height:1.2;}
:where(.wtyg-map-site_eyes_network) .p-badge{font-family:'JetBrains Mono',monospace; font-size:0.57rem; letter-spacing:0.08em; text-transform:uppercase; padding:2px 7px; border-radius:2px; display:inline-block; margin-bottom:12px;}
:where(.wtyg-map-site_eyes_network) .p-section{margin-bottom:11px;}
:where(.wtyg-map-site_eyes_network) .p-section h4{font-family:'JetBrains Mono',monospace; font-size:0.55rem; letter-spacing:0.12em; text-transform:uppercase; color:#5a6878; margin-bottom:4px; padding-bottom:3px; border-bottom:1px solid rgba(200,168,75,0.15);}
:where(.wtyg-map-site_eyes_network) .p-section p{font-size:0.84rem; line-height:1.78; color:#b0a898;}
:where(.wtyg-map-site_eyes_network) .p-section p .term{color:var(--accent); font-style:italic;}
:where(.wtyg-map-site_eyes_network) .p-section p strong{color:#c0b8a8; font-weight:500;}
:where(.wtyg-map-site_eyes_network) .conn-row{display:flex; flex-wrap:wrap; gap:4px;}
:where(.wtyg-map-site_eyes_network) .ct{font-size:0.63rem; padding:2px 7px; border:1px solid rgba(200,168,75,0.2); border-radius:3px; color:#6a6050; font-family:'JetBrains Mono',monospace; cursor:pointer; transition:all 0.15s;}
:where(.wtyg-map-site_eyes_network) .ct:hover{border-color:var(--accent); color:var(--accent);}
:where(.wtyg-map-site_eyes_network) .p-close{display:none;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="tt"],#wtyg-noid-tt){position:fixed; background:rgba(8,10,18,0.97); border:1px solid var(--border); border-radius:3px; padding:6px 10px; font-size:0.72rem; color:var(--muted); pointer-events:none; opacity:0; transition:opacity 0.1s; max-width:175px; z-index:100; line-height:1.5; font-family:'Spectral',serif; font-style:italic;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="map-hd"],#wtyg-noid-map-hd){position:absolute; top:0; left:0; right:0; z-index:401; padding:5px 10px; background:rgba(8,10,18,0.94); border-bottom:1px solid var(--border); font-family:'JetBrains Mono',monospace; font-size:0.53rem; letter-spacing:0.09em; text-transform:uppercase; color:var(--accent); display:flex; justify-content:space-between; align-items:center;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="map-body"],#wtyg-noid-map-body){position:absolute; inset:0; top:27px;}
:where(.wtyg-map-site_eyes_network) .leaflet-container{background:#0c1018 !important;}
:where(.wtyg-map-site_eyes_network) .leaflet-tooltip{background:rgba(8,10,18,0.95) !important; border:1px solid rgba(200,168,75,0.3) !important; border-radius:3px !important; color:#e8e0d0 !important; font-family:'Spectral',serif !important; box-shadow:none !important; padding:5px 9px !important;}
:where(.wtyg-map-site_eyes_network) .leaflet-tooltip::before{display:none !important;}
:where(.wtyg-map-site_eyes_network) .leaflet-control-attribution{background:rgba(8,10,18,0.7) !important; color:#404858 !important; font-size:8px !important;}
:where(.wtyg-map-site_eyes_network) .leaflet-control-attribution a{color:#505868 !important;}
:where(.wtyg-map-site_eyes_network) .edge{fill:none; stroke-opacity:0.07; stroke-width:1.2; transition:stroke-opacity 0.2s,stroke-width 0.2s;}
:where(.wtyg-map-site_eyes_network) .ctrl-edge{fill:none; stroke-opacity:0.12; stroke-width:1; stroke-dasharray:5,4; transition:stroke-opacity 0.2s;}
:where(.wtyg-map-site_eyes_network) .edge.lit,:where(.wtyg-map-site_eyes_network) .ctrl-edge.lit{stroke-opacity:0.85; stroke-width:2.2;}
:where(.wtyg-map-site_eyes_network) .edge.dim,:where(.wtyg-map-site_eyes_network) .ctrl-edge.dim{stroke-opacity:0.01;}
:where(.wtyg-map-site_eyes_network) .ng{cursor:pointer;}
:where(.wtyg-map-site_eyes_network) .ng:hover .ng-glow{opacity:0.22;}
:where(.wtyg-map-site_eyes_network) .ng.sel .ng-glow{opacity:0.28;}
:where(.wtyg-map-site_eyes_network) .ng-glow{transition:opacity 0.14s;}
:where(.wtyg-map-site_eyes_network) .nl{font-family:'Spectral',serif; font-size:10px; fill:rgba(200,192,178,0.78); pointer-events:none;}
:where(.wtyg-map-site_eyes_network) .nl-sm{font-family:'Spectral',serif; font-size:9px; fill:rgba(200,192,178,0.65); pointer-events:none;}
:where(.wtyg-map-site_eyes_network) .era-t{font-family:'JetBrains Mono',monospace; font-size:8.5px; letter-spacing:0.07em; text-transform:uppercase; fill:rgba(200,168,75,0.3);}
:where(.wtyg-map-site_eyes_network) .era-d{font-family:'EB Garamond',serif; font-style:italic; font-size:10px; fill:rgba(200,192,178,0.16);}
:where(.wtyg-map-site_eyes_network) .ctrl-lbl{font-family:'JetBrains Mono',monospace; font-size:7px; letter-spacing:0.07em; fill:rgba(200,168,75,0.6); pointer-events:none;}
:where(.wtyg-map-site_eyes_network) .trunk-line{stroke:rgba(200,168,75,0.12); stroke-width:1.5; fill:none; stroke-dasharray:2,8;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="map-hd"],#wtyg-noid-map-hd){position:absolute; top:0; left:0; right:0; z-index:401;
  padding:7px 12px 6px;
  background:rgba(8,10,18,0.94); border-bottom:1px solid var(--border);
  font-family:'JetBrains Mono',monospace; font-size:0.56rem;
  letter-spacing:0.1em; text-transform:uppercase; color:var(--accent);
  display:flex; justify-content:space-between; align-items:center;}
:where(.wtyg-map-site_eyes_network) :is([data-wtyg-id="map-body"],#wtyg-noid-map-body){position:absolute; inset:0; top:32px;}
:where(.wtyg-map-site_eyes_network) .leaflet-container{background:#0c1018 !important;}
:where(.wtyg-map-site_eyes_network) .leaflet-tooltip{background:rgba(8,10,18,0.95) !important;
  border:1px solid rgba(200,168,75,0.3) !important;
  border-radius:3px !important; color:#e8e0d0 !important;
  font-family:'Spectral',serif !important; box-shadow:none !important;
  padding:5px 9px !important;}
:where(.wtyg-map-site_eyes_network) .leaflet-tooltip::before{display:none !important;}
:where(.wtyg-map-site_eyes_network) .leaflet-control-attribution{background:rgba(8,10,18,0.7) !important; color:#404858 !important;}
:where(.wtyg-map-site_eyes_network) .leaflet-control-attribution a{color:#505868 !important;}
